import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"Kernel 日报 2026-11-18","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/18.md","filePath":"notes/kernel-digest/2026/11/18.md"}'),l={name:"notes/kernel-digest/2026/11/18.md"};function n(s,e,c,i,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-18" tabindex="-1">Kernel 日报 2026-11-18 <a class="header-anchor" href="#kernel-日报-2026-11-18" aria-label="Permalink to &quot;Kernel 日报 2026-11-18&quot;">​</a></h1><blockquote><p>生成时间：2026-11-18T01:42:19Z｜共 38 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-18 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_12b0d9a577ed-·-patch-ipsec-0-2-xfrm-iptfs-fix-a-panic-and-a-use-after-free-on-output" tabindex="-1"><code>12b0d9a577ed</code> · <a href="https://lore.kernel.org/all/b56bbced-a8b0-4ae9-80b4-1958ea36684c@mid.andrii.net/" target="_blank" rel="noreferrer">[PATCH ipsec 0/2] xfrm: iptfs: fix a panic and a use-after-free on output</a> <a class="header-anchor" href="#_12b0d9a577ed-·-patch-ipsec-0-2-xfrm-iptfs-fix-a-panic-and-a-use-after-free-on-output" aria-label="Permalink to &quot;`12b0d9a577ed` · [[PATCH ipsec 0/2] xfrm: iptfs: fix a panic and a use-after-free on output](https://lore.kernel.org/all/b56bbced-a8b0-4ae9-80b4-1958ea36684c@mid.andrii.net/)&quot;">​</a></h3><p><em>Andrii Tereshchenko (<a href="mailto:opensource@andrii.net" target="_blank" rel="noreferrer">opensource@andrii.net</a>)｜netdev｜网络</em></p><p>本系列修复 IP-TFS 输出路径（net/xfrm/xfrm_iptfs.c）中的两个 bug：一个是向 clone skb 的共享 frag_list 追加导致 panic，另一个是延迟队列上的 skb 持有已释放的 dst 导致 use-after-free。两个 bug 自 v6.14 引入，普通 TCP 重传即可触发，无特权用户在允许 user namespace 的系统上可借此 panic 内核。</p><blockquote><p><strong>学习价值</strong>：一个完整的 security 相关 bug 修复系列封面，展示了从复现、诊断到修复的全流程，并涉及无特权触发路径的安全评估。</p></blockquote><h3 id="_3684d9b9a919-·-patch-net-0-3-tcp-avoid-integer-wraps-in-the-rtt-estimator-and-the-rto" tabindex="-1"><code>3684d9b9a919</code> · <a href="https://lore.kernel.org/all/20261118005048.53393-1-mason@kernel.org/" target="_blank" rel="noreferrer">[PATCH net 0/3] tcp: avoid integer wraps in the RTT estimator and the RTO</a> <a class="header-anchor" href="#_3684d9b9a919-·-patch-net-0-3-tcp-avoid-integer-wraps-in-the-rtt-estimator-and-the-rto" aria-label="Permalink to &quot;`3684d9b9a919` · [[PATCH net 0/3] tcp: avoid integer wraps in the RTT estimator and the RTO](https://lore.kernel.org/all/20261118005048.53393-1-mason@kernel.org/)&quot;">​</a></h3><p><em>Chris Mason (<a href="mailto:mason@kernel.org" target="_blank" rel="noreferrer">mason@kernel.org</a>)｜netdev｜网络</em></p><p>本系列三补丁防止超大 RTT 样本导致 TCP RTT 估算器的 u32 字段回绕：补丁 1 保证 __tcp_set_rto() 不返回 0；补丁 2 让 tcp_rtt_estimator() 将每个样本钳制到 120 秒，覆盖 ACK、SACK 和 TSecr 样本；补丁 3 让 tcp_rtt_tsopt_us() 拒绝超过 120 秒的 TSecr 样本。基于 v7.4-rc3。</p><blockquote><p><strong>学习价值</strong>：完整呈现了 TCP RTT/RTO 估算链路（srtt、mdev、rttvar）的溢出防护思路，适合学习 TCP 计时器内部机制。</p></blockquote><h3 id="c6ba22e6482b-·-patch-0-3-rust-block-add-rbrd-a-ram-backed-block-driver" tabindex="-1"><code>c6ba22e6482b</code> · <a href="https://lore.kernel.org/all/20261117233211.3137168-1-vitaly.wool@konsulko.se/" target="_blank" rel="noreferrer">[PATCH 0/3] rust: block: add rbrd, a RAM backed block driver</a> <a class="header-anchor" href="#c6ba22e6482b-·-patch-0-3-rust-block-add-rbrd-a-ram-backed-block-driver" aria-label="Permalink to &quot;`c6ba22e6482b` · [[PATCH 0/3] rust: block: add rbrd, a RAM backed block driver](https://lore.kernel.org/all/20261117233211.3137168-1-vitaly.wool@konsulko.se/)&quot;">​</a></h3><p><em>Vitaly Wool (<a href="mailto:vitaly.wool@konsulko.se" target="_blank" rel="noreferrer">vitaly.wool@konsulko.se</a>)｜rust-for-linux｜Rust in Linux</em></p><p>本系列添加 Rust 编写的 RAM 块设备 rbrd 及所需抽象：1) blk-mq 驱动的 bio segment 迭代与请求访问器；2) Page 的引用计数、裸指针转换和 page-&gt;private 位自旋锁；3) 通过 configfs 配置的驱动本身。page 保存在原子指针扁平数组中实现无锁查找/添加/删除；与 brd 不同，rbrd 用位自旋锁保证读写不会同时拷贝同一 page。</p><blockquote><p><strong>学习价值</strong>：作为完整的三补丁系列，展示了从底层抽象到完整驱动的 Rust 内核开发全流程，非常值得通读。</p></blockquote><h3 id="cb72b626bf2a-·-patch-v2-1-2-fs-proc-task-mmu-reset-walk-end-before-each-pagemap-walk" tabindex="-1"><code>cb72b626bf2a</code> · <a href="https://lore.kernel.org/all/20261118-pagemap-walk-end-v2-1-94cd92d838b3@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 1/2] fs/proc/task_mmu: reset walk_end before each pagemap walk</a> <a class="header-anchor" href="#cb72b626bf2a-·-patch-v2-1-2-fs-proc-task-mmu-reset-walk-end-before-each-pagemap-walk" aria-label="Permalink to &quot;`cb72b626bf2a` · [[PATCH v2 1/2] fs/proc/task_mmu: reset walk_end before each pagemap walk](https://lore.kernel.org/all/20261118-pagemap-walk-end-v2-1-94cd92d838b3@gmail.com/)&quot;">​</a></h3><p><em>Matthew Salsamendi via B4 Relay (<a href="mailto:devnull+matthewsalsamendi.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+matthewsalsamendi.gmail.com@kernel.org</a>)｜linux-mm｜内存管理</em></p><p>修复 PAGEMAP_SCAN 在 buffer 填满后恢复扫描时可能返回超出过期 walk_end 的 range 的问题，该 bug 曾导致生产环境游戏服务器的 dirty-page tracking 中止。修复方式是在每次 pagemap walk 前重置 walk_end，确保完整扫描正确报告结束位置，HugeTLB 部分请求保留重试地址。</p><blockquote><p><strong>学习价值</strong>：展示了 ioctl 状态机中残留状态导致的真实生产 bug，对理解 task_mmu 的 PAGEMAP_SCAN 实现细节很有帮助。</p></blockquote><h3 id="c9cd219a6c7e-·-new-amdgpu-linux-patches-from-valve-aim-to-reduce-stuttering-with-steam-play-games" tabindex="-1"><code>c9cd219a6c7e</code> · <a href="https://www.phoronix.com/news/AMDGPU-Sparse-Gaming-Valve" target="_blank" rel="noreferrer">New AMDGPU Linux Patches From Valve Aim To Reduce Stuttering With Steam Play Games</a> <a class="header-anchor" href="#c9cd219a6c7e-·-new-amdgpu-linux-patches-from-valve-aim-to-reduce-stuttering-with-steam-play-games" aria-label="Permalink to &quot;`c9cd219a6c7e` · [New AMDGPU Linux Patches From Valve Aim To Reduce Stuttering With Steam Play Games](https://www.phoronix.com/news/AMDGPU-Sparse-Gaming-Valve)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜核心内核</em></p><p>Valve Linux 图形驱动团队的 Natalie Vock 发送了新版 AMDGPU 内核驱动补丁，旨在为通过 Steam Play（Proton）在 Linux 上运行的新 Windows 游戏带来显著的卡顿减少。</p><blockquote><p><strong>学习价值</strong>：展示了游戏厂商如何直接参与内核图形驱动开发，是理解 AMDGPU 驱动与实际性能调优结合的好案例。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（3 条）</li><li><strong>网络</strong>（10 条）</li><li><strong>调度器</strong>（1 条）</li><li><strong>文件系统与存储</strong>（1 条）</li><li><strong>安全</strong>（2 条）</li><li><strong>Rust in Linux</strong>（14 条）</li><li><strong>核心内核</strong>（1 条）</li><li><strong>版本发布动态</strong>（2 条）</li><li><strong>其他动态</strong>（4 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="_4f484acfd9c1-·-patch-v2-2-2-selftests-mm-cover-pagemap-scan-refill-and-hugetlb-retry" tabindex="-1"><code>4f484acfd9c1</code> · <a href="https://lore.kernel.org/all/20261118-pagemap-walk-end-v2-2-94cd92d838b3@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 2/2] selftests/mm: cover PAGEMAP_SCAN refill and HugeTLB retry</a> <a class="header-anchor" href="#_4f484acfd9c1-·-patch-v2-2-2-selftests-mm-cover-pagemap-scan-refill-and-hugetlb-retry" aria-label="Permalink to &quot;`4f484acfd9c1` · [[PATCH v2 2/2] selftests/mm: cover PAGEMAP_SCAN refill and HugeTLB retry](https://lore.kernel.org/all/20261118-pagemap-walk-end-v2-2-94cd92d838b3@gmail.com/)&quot;">​</a></h3><p><em>Matthew Salsamendi via B4 Relay (<a href="mailto:devnull+matthewsalsamendi.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+matthewsalsamendi.gmail.com@kernel.org</a>)｜linux-mm</em></p><p>为 PAGEMAP_SCAN 补充 selftests/mm 测试：验证扫描 513 个不连续 dirty page 时 buffer refill 后能返回所有 range 并正确设置 walk_end；对 HugeTLB 页面验证部分扫描后从 walk_end 重试能返回整页并完成 write-protect。测试覆盖了前一个补丁修复的 walk_end 重置逻辑。</p><blockquote><p><strong>学习价值</strong>：展示了如何针对内核 bug 修复编写回归测试，是学习 selftests/mm 框架和 PAGEMAP_SCAN ioctl 语义的好材料。</p></blockquote><h3 id="_4e8135ee3fc2-·-patch-v2-0-2-fs-proc-fix-pagemap-scan-walk-end-after-a-buffer-refill" tabindex="-1"><code>4e8135ee3fc2</code> · <a href="https://lore.kernel.org/all/20261118-pagemap-walk-end-v2-0-94cd92d838b3@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 0/2] fs/proc: fix PAGEMAP_SCAN walk_end after a buffer refill</a> <a class="header-anchor" href="#_4e8135ee3fc2-·-patch-v2-0-2-fs-proc-fix-pagemap-scan-walk-end-after-a-buffer-refill" aria-label="Permalink to &quot;`4e8135ee3fc2` · [[PATCH v2 0/2] fs/proc: fix PAGEMAP_SCAN walk_end after a buffer refill](https://lore.kernel.org/all/20261118-pagemap-walk-end-v2-0-94cd92d838b3@gmail.com/)&quot;">​</a></h3><p><em>Matthew Salsamendi via B4 Relay (<a href="mailto:devnull+matthewsalsamendi.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+matthewsalsamendi.gmail.com@kernel.org</a>)｜linux-mm</em></p><p>本系列共 2 个补丁，修复 fs/proc/task_mmu 中 PAGEMAP_SCAN 在 buffer refill 后 walk_end 未重置的问题，并附带 selftests 覆盖 refill 和 HugeTLB retry 场景。作者确认在未打补丁内核上 refill 测试失败，v2 上全部 121 个测试通过。</p><blockquote><p><strong>学习价值</strong>：一个典型的『bug 修复 + 回归测试』完整补丁系列，可学习内核补丁迭代流程与测试验证方法。</p></blockquote><h3 id="cb72b626bf2a-·-patch-v2-1-2-fs-proc-task-mmu-reset-walk-end-before-each-pagemap-walk-1" tabindex="-1"><code>cb72b626bf2a</code> · <a href="https://lore.kernel.org/all/20261118-pagemap-walk-end-v2-1-94cd92d838b3@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 1/2] fs/proc/task_mmu: reset walk_end before each pagemap walk</a> <a class="header-anchor" href="#cb72b626bf2a-·-patch-v2-1-2-fs-proc-task-mmu-reset-walk-end-before-each-pagemap-walk-1" aria-label="Permalink to &quot;`cb72b626bf2a` · [[PATCH v2 1/2] fs/proc/task_mmu: reset walk_end before each pagemap walk](https://lore.kernel.org/all/20261118-pagemap-walk-end-v2-1-94cd92d838b3@gmail.com/)&quot;">​</a></h3><p><em>Matthew Salsamendi via B4 Relay (<a href="mailto:devnull+matthewsalsamendi.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+matthewsalsamendi.gmail.com@kernel.org</a>)｜linux-mm</em></p><p>修复 PAGEMAP_SCAN 在 buffer 填满后恢复扫描时可能返回超出过期 walk_end 的 range 的问题，该 bug 曾导致生产环境游戏服务器的 dirty-page tracking 中止。修复方式是在每次 pagemap walk 前重置 walk_end，确保完整扫描正确报告结束位置，HugeTLB 部分请求保留重试地址。</p><blockquote><p><strong>学习价值</strong>：展示了 ioctl 状态机中残留状态导致的真实生产 bug，对理解 task_mmu 的 PAGEMAP_SCAN 实现细节很有帮助。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_5b37e0d46bec-·-patch-net-vhost-vsock-annotate-lockless-accesses-to-guest-cid" tabindex="-1"><code>5b37e0d46bec</code> · <a href="https://lore.kernel.org/all/20261117164916.2332953-1-phind.uet@gmail.com/" target="_blank" rel="noreferrer">[PATCH net] vhost/vsock: annotate lockless accesses to guest_cid</a> <a class="header-anchor" href="#_5b37e0d46bec-·-patch-net-vhost-vsock-annotate-lockless-accesses-to-guest-cid" aria-label="Permalink to &quot;`5b37e0d46bec` · [[PATCH net] vhost/vsock: annotate lockless accesses to guest_cid](https://lore.kernel.org/all/20261117164916.2332953-1-phind.uet@gmail.com/)&quot;">​</a></h3><p><em>Nguyen Dinh Phi (<a href="mailto:phind.uet@gmail.com" target="_blank" rel="noreferrer">phind.uet@gmail.com</a>)｜netdev</em></p><p>vhost_vsock 的 guest_cid 在 vhost_vsock_set_cid() 中持 vhost_vsock_mutex 写入，但在 vhost_vsock_handle_tx_kick() 和 vhost_vsock_get() 中无锁读取，KCSAN 会报告 data-race。补丁为这些无锁访问添加 READ_ONCE/WRITE_ONCE 注解以消除竞争告警。</p><blockquote><p><strong>学习价值</strong>：学习 KCSAN data-race 报告分析和 READ_ONCE 注解处理的典型案例，适合了解并发访问标注规范。</p></blockquote><h3 id="_8ef5778a3257-·-patch-net-v2-vsock-only-undo-ss-connecting-when-connect-fails" tabindex="-1"><code>8ef5778a3257</code> · <a href="https://lore.kernel.org/all/20261117-vsock-connect-close-v2-1-db5388323770@meta.com/" target="_blank" rel="noreferrer">[PATCH net v2] vsock: only undo SS_CONNECTING when connect() fails</a> <a class="header-anchor" href="#_8ef5778a3257-·-patch-net-v2-vsock-only-undo-ss-connecting-when-connect-fails" aria-label="Permalink to &quot;`8ef5778a3257` · [[PATCH net v2] vsock: only undo SS_CONNECTING when connect() fails](https://lore.kernel.org/all/20261117-vsock-connect-close-v2-1-db5388323770@meta.com/)&quot;">​</a></h3><p><em>Bobby Eshleman (<a href="mailto:bobbyeshleman@meta.com" target="_blank" rel="noreferrer">bobbyeshleman@meta.com</a>)｜netdev</em></p><p>修复 vsock_connect() 中的状态机问题：connect() 睡眠期间 transport 可能完成握手后又重置连接，connect() 醒来发现 sk_err 后错误地将 SS_CONNECTED 状态回退到 SS_UNCONNECTED。后续对其他 transport 的 connect() 会释放原 transport 导致问题。修复为仅在 connect() 确实失败时才回退状态。</p><blockquote><p><strong>学习价值</strong>：典型的 socket 状态机竞态分析案例，展示了对锁释放窗口内状态变化的细致推理，对学习网络子系统的并发设计很有价值。</p></blockquote><h3 id="_54111fe683dc-·-patch-ipsec-2-2-xfrm-iptfs-hold-the-dst-while-a-packet-waits-on-the-output-queue" tabindex="-1"><code>54111fe683dc</code> · <a href="https://lore.kernel.org/all/45f802a2-c639-44bd-aba0-5c81e2198c9e@mid.andrii.net/" target="_blank" rel="noreferrer">[PATCH ipsec 2/2] xfrm: iptfs: hold the dst while a packet waits on the output queue</a> <a class="header-anchor" href="#_54111fe683dc-·-patch-ipsec-2-2-xfrm-iptfs-hold-the-dst-while-a-packet-waits-on-the-output-queue" aria-label="Permalink to &quot;`54111fe683dc` · [[PATCH ipsec 2/2] xfrm: iptfs: hold the dst while a packet waits on the output queue](https://lore.kernel.org/all/45f802a2-c639-44bd-aba0-5c81e2198c9e@mid.andrii.net/)&quot;">​</a></h3><p><em>Andrii Tereshchenko (<a href="mailto:opensource@andrii.net" target="_blank" rel="noreferrer">opensource@andrii.net</a>)｜netdev</em></p><p>修复 iptfs_output_collect() 将 skb 入队到延迟队列时未持有 dst 引用的问题：本地生成的 TCP 通过 skb_dst_set_noref() 附加缓存路由，仅在 RCU 读临界区内有效，skb 在队列上存活超过该临界区后 TCP 重传定时器释放 dst，导致 iptfs_output_queued() 读到已释放的 dst（KASAN use-after-free）。</p><blockquote><p><strong>学习价值</strong>：展示了 skb_dst_set_noref 的 RCU 生命周期约束如何被延迟队列破坏，是理解 dst 引用计数与 RCU 交互的绝佳案例。</p></blockquote><h3 id="_0bdd64881783-·-patch-ipsec-1-2-xfrm-iptfs-don-t-modify-the-shared-info-of-cloned-skbs-on-output" tabindex="-1"><code>0bdd64881783</code> · <a href="https://lore.kernel.org/all/c1e999b5-15ee-468d-81c5-530a560e84df@mid.andrii.net/" target="_blank" rel="noreferrer">[PATCH ipsec 1/2] xfrm: iptfs: don&#39;t modify the shared info of cloned skbs on output</a> <a class="header-anchor" href="#_0bdd64881783-·-patch-ipsec-1-2-xfrm-iptfs-don-t-modify-the-shared-info-of-cloned-skbs-on-output" aria-label="Permalink to &quot;`0bdd64881783` · [[PATCH ipsec 1/2] xfrm: iptfs: don&#39;t modify the shared info of cloned skbs on output](https://lore.kernel.org/all/c1e999b5-15ee-468d-81c5-530a560e84df@mid.andrii.net/)&quot;">​</a></h3><p><em>Andrii Tereshchenko (<a href="mailto:opensource@andrii.net" target="_blank" rel="noreferrer">opensource@andrii.net</a>)｜netdev</em></p><p>修复 iptfs_output_queued() 聚合内层包时向 clone skb 的共享 skb_shinfo 追加 frag_list 的问题：TCP 重传队列中的原始 skb 与发送的 clone 共享 shared_info，向 clone 追加会污染原始 skb，导致内核 skb_over_panic。修复为不修改 clone skb 的共享信息。</p><blockquote><p><strong>学习价值</strong>：深入讲解 skb clone 与 skb_shared_info 共享语义的经典陷阱，对理解 TCP 发送路径和 skb 生命周期极有价值。</p></blockquote><h3 id="_12b0d9a577ed-·-patch-ipsec-0-2-xfrm-iptfs-fix-a-panic-and-a-use-after-free-on-output-1" tabindex="-1"><code>12b0d9a577ed</code> · <a href="https://lore.kernel.org/all/b56bbced-a8b0-4ae9-80b4-1958ea36684c@mid.andrii.net/" target="_blank" rel="noreferrer">[PATCH ipsec 0/2] xfrm: iptfs: fix a panic and a use-after-free on output</a> <a class="header-anchor" href="#_12b0d9a577ed-·-patch-ipsec-0-2-xfrm-iptfs-fix-a-panic-and-a-use-after-free-on-output-1" aria-label="Permalink to &quot;`12b0d9a577ed` · [[PATCH ipsec 0/2] xfrm: iptfs: fix a panic and a use-after-free on output](https://lore.kernel.org/all/b56bbced-a8b0-4ae9-80b4-1958ea36684c@mid.andrii.net/)&quot;">​</a></h3><p><em>Andrii Tereshchenko (<a href="mailto:opensource@andrii.net" target="_blank" rel="noreferrer">opensource@andrii.net</a>)｜netdev</em></p><p>本系列修复 IP-TFS 输出路径（net/xfrm/xfrm_iptfs.c）中的两个 bug：一个是向 clone skb 的共享 frag_list 追加导致 panic，另一个是延迟队列上的 skb 持有已释放的 dst 导致 use-after-free。两个 bug 自 v6.14 引入，普通 TCP 重传即可触发，无特权用户在允许 user namespace 的系统上可借此 panic 内核。</p><blockquote><p><strong>学习价值</strong>：一个完整的 security 相关 bug 修复系列封面，展示了从复现、诊断到修复的全流程，并涉及无特权触发路径的安全评估。</p></blockquote><h3 id="_669b2b2daf11-·-patch-net-3-3-tcp-reject-rtt-samples-from-tsecr-above-120-s" tabindex="-1"><code>669b2b2daf11</code> · <a href="https://lore.kernel.org/all/20261118005048.53393-4-mason@kernel.org/" target="_blank" rel="noreferrer">[PATCH net 3/3] tcp: reject RTT samples from TSecr above 120 s</a> <a class="header-anchor" href="#_669b2b2daf11-·-patch-net-3-3-tcp-reject-rtt-samples-from-tsecr-above-120-s" aria-label="Permalink to &quot;`669b2b2daf11` · [[PATCH net 3/3] tcp: reject RTT samples from TSecr above 120 s](https://lore.kernel.org/all/20261118005048.53393-4-mason@kernel.org/)&quot;">​</a></h3><p><em>Chris Mason (<a href="mailto:mason@kernel.org" target="_blank" rel="noreferrer">mason@kernel.org</a>)｜netdev</em></p><p>修复 tcp_rtt_tsopt_us() 接受过大的 TSecr 回显样本（最多 2147 s）的问题：当 TSecr 回显旧时间戳时，样本实际是该时间戳的年龄而非 RTT，未 clamp 的样本传入拥塞控制，且 tcp_rcv_rtt_update() 的 u32 乘法在 536.9 s 以上会溢出。修复为拒绝超过 120 s 的 TSecr 样本。</p><blockquote><p><strong>学习价值</strong>：展示了 TCP RTT 估算中时间戳语义混淆（RTT vs 时间戳年龄）的隐蔽 bug，对理解 TCP 时间戳与 RTT 采样机制很有帮助。</p></blockquote><h3 id="e936c5d1d7dc-·-patch-net-2-3-tcp-clamp-rtt-samples-in-tcp-rtt-estimator" tabindex="-1"><code>e936c5d1d7dc</code> · <a href="https://lore.kernel.org/all/20261118005048.53393-3-mason@kernel.org/" target="_blank" rel="noreferrer">[PATCH net 2/3] tcp: clamp RTT samples in tcp_rtt_estimator()</a> <a class="header-anchor" href="#e936c5d1d7dc-·-patch-net-2-3-tcp-clamp-rtt-samples-in-tcp-rtt-estimator" aria-label="Permalink to &quot;`e936c5d1d7dc` · [[PATCH net 2/3] tcp: clamp RTT samples in tcp_rtt_estimator()](https://lore.kernel.org/all/20261118005048.53393-3-mason@kernel.org/)&quot;">​</a></h3><p><em>Chris Mason (<a href="mailto:mason@kernel.org" target="_blank" rel="noreferrer">mason@kernel.org</a>)｜netdev</em></p><p>修复 tcp_rtt_estimator() 中 u32 微秒字段溢出问题：srtt_us 存储 8 倍平滑 RTT，在 RTT 超过 536.9 s 时回绕。样本可来自 TSecr（最多 2147 s）或从未重传 segment 的 SACK 年龄，后者自 commit 740b0f1841f6 切换到 usec 分辨率后即可触发溢出。修复为在 estimator 中 clamp 样本。</p><blockquote><p><strong>学习价值</strong>：细致分析定点数表示的溢出边界（8 倍 RTT 的 u32 上限），是学习 TCP RTT 估算内部数据表示与溢出审计的好例子。</p></blockquote><h3 id="d301860ac79f-·-patch-net-1-3-tcp-don-t-let-tcp-set-rto-return-0" tabindex="-1"><code>d301860ac79f</code> · <a href="https://lore.kernel.org/all/20261118005048.53393-2-mason@kernel.org/" target="_blank" rel="noreferrer">[PATCH net 1/3] tcp: don&#39;t let __tcp_set_rto() return 0</a> <a class="header-anchor" href="#d301860ac79f-·-patch-net-1-3-tcp-don-t-let-tcp-set-rto-return-0" aria-label="Permalink to &quot;`d301860ac79f` · [[PATCH net 1/3] tcp: don&#39;t let __tcp_set_rto() return 0](https://lore.kernel.org/all/20261118005048.53393-2-mason@kernel.org/)&quot;">​</a></h3><p><em>Chris Mason (<a href="mailto:mason@kernel.org" target="_blank" rel="noreferrer">mason@kernel.org</a>)｜netdev</em></p><p>修复 __tcp_set_rto() 可能返回 0 的问题。该函数用 u32 算术计算 RTO（(srtt_us &gt;&gt; 3) + rttvar_us）且无下界，一旦求和溢出回绕，tcp_retransmit_timer() 的指数退避（翻倍 icsk_rto）就会失效。修复方式是保证 __tcp_set_rto() 永不返回 0，使退避机制在任何 RTT 估算器状态下都能恢复。</p><blockquote><p><strong>学习价值</strong>：展示了整型回绕如何破坏 TCP 重传退避机制，是理解 RTO 计算路径与防御性编程的好案例。</p></blockquote><h3 id="_3684d9b9a919-·-patch-net-0-3-tcp-avoid-integer-wraps-in-the-rtt-estimator-and-the-rto-1" tabindex="-1"><code>3684d9b9a919</code> · <a href="https://lore.kernel.org/all/20261118005048.53393-1-mason@kernel.org/" target="_blank" rel="noreferrer">[PATCH net 0/3] tcp: avoid integer wraps in the RTT estimator and the RTO</a> <a class="header-anchor" href="#_3684d9b9a919-·-patch-net-0-3-tcp-avoid-integer-wraps-in-the-rtt-estimator-and-the-rto-1" aria-label="Permalink to &quot;`3684d9b9a919` · [[PATCH net 0/3] tcp: avoid integer wraps in the RTT estimator and the RTO](https://lore.kernel.org/all/20261118005048.53393-1-mason@kernel.org/)&quot;">​</a></h3><p><em>Chris Mason (<a href="mailto:mason@kernel.org" target="_blank" rel="noreferrer">mason@kernel.org</a>)｜netdev</em></p><p>本系列三补丁防止超大 RTT 样本导致 TCP RTT 估算器的 u32 字段回绕：补丁 1 保证 __tcp_set_rto() 不返回 0；补丁 2 让 tcp_rtt_estimator() 将每个样本钳制到 120 秒，覆盖 ACK、SACK 和 TSecr 样本；补丁 3 让 tcp_rtt_tsopt_us() 拒绝超过 120 秒的 TSecr 样本。基于 v7.4-rc3。</p><blockquote><p><strong>学习价值</strong>：完整呈现了 TCP RTT/RTO 估算链路（srtt、mdev、rttvar）的溢出防护思路，适合学习 TCP 计时器内部机制。</p></blockquote><h3 id="_0161b70f86ef-·-patch-net-dsa-mt7530-fix-regulator-leak-in-mt7530-setup" tabindex="-1"><code>0161b70f86ef</code> · <a href="https://lore.kernel.org/all/20261118014114.1855-1-laixiangwu@cmss.chinamobile.com/" target="_blank" rel="noreferrer">[PATCH] net: dsa: mt7530: fix regulator leak in mt7530_setup()</a> <a class="header-anchor" href="#_0161b70f86ef-·-patch-net-dsa-mt7530-fix-regulator-leak-in-mt7530-setup" aria-label="Permalink to &quot;`0161b70f86ef` · [[PATCH] net: dsa: mt7530: fix regulator leak in mt7530_setup()](https://lore.kernel.org/all/20261118014114.1855-1-laixiangwu@cmss.chinamobile.com/)&quot;">​</a></h3><p><em>Xiangwu Lai (<a href="mailto:laixiangwu@cmss.chinamobile.com" target="_blank" rel="noreferrer">laixiangwu@cmss.chinamobile.com</a>)｜netdev</em></p><p>该补丁修复了 net: dsa: mt7530 驱动中 mt7530_setup() 的 regulator 泄漏问题。原代码在启用 &quot;core&quot; 和 &quot;io&quot; 两个 regulator 后，后续的多个错误路径（如 reset 超时、不支持的 chip ID、VLAN 设置失败等）均未将其关闭，导致 setup 失败后 regulator 一直保持使能。补丁通过新增两个错误标签，在失败时释放已启用的 regulator，并针对 MT7621 共用 sw_setup 回调但跳过 regulator 段的情况做了保护处理。</p><blockquote><p><strong>学习价值</strong>：这是学习内核驱动错误处理路径（error label 模式）和资源对称管理（enable/disable 配对）的好案例，尤其适合理解 DSA 子系统中共享回调的兼容性处理。</p></blockquote><h2 id="调度器" tabindex="-1">调度器 <a class="header-anchor" href="#调度器" aria-label="Permalink to &quot;调度器&quot;">​</a></h2><h3 id="_437b24420188-·-patch-v4-cpufreq-cppc-enable-boost-by-default" tabindex="-1"><code>437b24420188</code> · <a href="https://lore.kernel.org/all/20261118013558.3075038-1-zhangpengjie2@huawei.com/" target="_blank" rel="noreferrer">[PATCH v4] cpufreq: CPPC: Enable boost by default</a> <a class="header-anchor" href="#_437b24420188-·-patch-v4-cpufreq-cppc-enable-boost-by-default" aria-label="Permalink to &quot;`437b24420188` · [[PATCH v4] cpufreq: CPPC: Enable boost by default](https://lore.kernel.org/all/20261118013558.3075038-1-zhangpengjie2@huawei.com/)&quot;">​</a></h3><p><em>Pengjie Zhang (<a href="mailto:zhangpengjie2@huawei.com" target="_blank" rel="noreferrer">zhangpengjie2@huawei.com</a>)｜lkml</em></p><p>该补丁修改 CPPC cpufreq 驱动，当 Highest Performance 超过 Nominal Performance 时默认启用 boost（设置 .boost_enabled = true），免去用户态手动开启的步骤。由于 cppc_cpufreq_cpu_init() 会在 highest_perf &gt; nominal_perf 时设置 policy-&gt;boost_supported，cpufreq core 只会对支持 boost 的策略默认启用。</p><blockquote><p><strong>学习价值</strong>：学习 cpufreq core 与驱动间 boost 机制交互的绝佳实例，展示了 policy-&gt;boost_supported 与驱动标志的协作设计。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="_0fda910d4c8c-·-btrfs-seeks-to-deal-with-ai-newbies-without-common-senses-doing-more-harm-than-good" tabindex="-1"><code>0fda910d4c8c</code> · <a href="https://www.phoronix.com/news/Btrfs-LLM-Newbies-Guidelines" target="_blank" rel="noreferrer">Btrfs Seeks To Deal With AI &amp; &quot;Newbies Without Common Senses&quot; Doing More Harm Than Good</a> <a class="header-anchor" href="#_0fda910d4c8c-·-btrfs-seeks-to-deal-with-ai-newbies-without-common-senses-doing-more-harm-than-good" aria-label="Permalink to &quot;`0fda910d4c8c` · [Btrfs Seeks To Deal With AI &amp; &quot;Newbies Without Common Senses&quot; Doing More Harm Than Good](https://www.phoronix.com/news/Btrfs-LLM-Newbies-Guidelines)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Btrfs 文件系统开发者计划在 Linux Git 中引入新的补丁提交准则，以应对 AI/LLM 生成的低质量补丁以及缺乏常识的新手贡献带来的负面影响。</p><blockquote><p><strong>学习价值</strong>：反映了 AI 时代内核子系统维护者面临的贡献质量挑战，对理解 Btrfs 社区治理和补丁流程有参考价值。</p></blockquote><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><h3 id="_4e9cb77047b9-·-security-updates-for-tuesday" tabindex="-1"><code>4e9cb77047b9</code> · <a href="https://lwn.net/Articles/1108140/" target="_blank" rel="noreferrer">Security updates for Tuesday</a> <a class="header-anchor" href="#_4e9cb77047b9-·-security-updates-for-tuesday" aria-label="Permalink to &quot;`4e9cb77047b9` · [Security updates for Tuesday](https://lwn.net/Articles/1108140/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>AlmaLinux 等发行版发布了大量安全更新，涉及 .NET、bind、glibc、firefox、flatpak、gcc 等众多软件包。</p><blockquote><p><strong>学习价值</strong>：属于发行版层面的安全公告汇总，可帮助学习者了解用户态软件供应链安全与内核安全的边界。</p></blockquote><h3 id="e19b35a525ba-·-java4shell-vulnerability-for-openjdk-java-that-can-lead-to-remote-code-execution" tabindex="-1"><code>e19b35a525ba</code> · <a href="https://www.phoronix.com/news/Java4Shell-Vulnerability" target="_blank" rel="noreferrer">Java4Shell Vulnerability For OpenJDK Java That Can Lead To Remote Code Execution</a> <a class="header-anchor" href="#e19b35a525ba-·-java4shell-vulnerability-for-openjdk-java-that-can-lead-to-remote-code-execution" aria-label="Permalink to &quot;`e19b35a525ba` · [Java4Shell Vulnerability For OpenJDK Java That Can Lead To Remote Code Execution](https://www.phoronix.com/news/Java4Shell-Vulnerability)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Java4Shell 漏洞被公开披露，这是 AI 与 LLM 时代又一个高知名度的 OpenJDK Java 安全漏洞，可能导致远程代码执行。</p><blockquote><p><strong>学习价值</strong>：用户态运行时安全问题，与内核学习关联较弱，但可作为理解 RCE 类漏洞影响面的背景阅读。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_0febdb1d4120-·-patch-maintainers-add-rust-for-linux-list-to-binder" tabindex="-1"><code>0febdb1d4120</code> · <a href="https://lore.kernel.org/all/20261117233901.2212899-1-cmllamas@google.com/" target="_blank" rel="noreferrer">[PATCH] MAINTAINERS: add rust-for-linux list to binder</a> <a class="header-anchor" href="#_0febdb1d4120-·-patch-maintainers-add-rust-for-linux-list-to-binder" aria-label="Permalink to &quot;`0febdb1d4120` · [[PATCH] MAINTAINERS: add rust-for-linux list to binder](https://lore.kernel.org/all/20261117233901.2212899-1-cmllamas@google.com/)&quot;">​</a></h3><p><em>Carlos Llamas (<a href="mailto:cmllamas@google.com" target="_blank" rel="noreferrer">cmllamas@google.com</a>)｜rust-for-linux</em></p><p>在 MAINTAINERS 文件的 ANDROID DRIVERS 条目中加入 rust-for-linux 邮件列表。由于旧 C 版 binder 驱动已在 commit fd2bc059ed46 中删除，drivers/android/ 目录现在只包含 Rust 版 binder，因此需要更新维护者列表。</p><blockquote><p><strong>学习价值</strong>：反映了 Android binder 驱动已完全迁移到 Rust 的里程碑，可了解 MAINTAINERS 文件维护流程。</p></blockquote><h3 id="_097465850d65-·-patch-3-3-rust-block-add-rbrd-a-ram-backed-block-driver" tabindex="-1"><code>097465850d65</code> · <a href="https://lore.kernel.org/all/20261117233211.3137168-4-vitaly.wool@konsulko.se/" target="_blank" rel="noreferrer">[PATCH 3/3] rust: block: add rbrd, a RAM backed block driver</a> <a class="header-anchor" href="#_097465850d65-·-patch-3-3-rust-block-add-rbrd-a-ram-backed-block-driver" aria-label="Permalink to &quot;`097465850d65` · [[PATCH 3/3] rust: block: add rbrd, a RAM backed block driver](https://lore.kernel.org/all/20261117233211.3137168-4-vitaly.wool@konsulko.se/)&quot;">​</a></h3><p><em>Vitaly Wool (<a href="mailto:vitaly.wool@konsulko.se" target="_blank" rel="noreferrer">vitaly.wool@konsulko.se</a>)｜rust-for-linux</em></p><p>新增用 Rust 编写的内存块设备驱动 rbrd，基于 rnull 框架、行为类似 brd：首次写入时分配 page，未写区域读出零，discard 释放完整覆盖的 page。设备通过 configfs 创建（power、blocksize、size 属性），page 保存在上电时分配的原子指针扁平数组中，查找用 Page::try_get_raw() 投机取引用并复查槽位，插入用 compare-and-exchange，全程无锁。</p><blockquote><p><strong>学习价值</strong>：是学习 Rust 块设备驱动开发和无锁 page 管理的绝佳参考实现。</p></blockquote><h3 id="_1cfa2b73dc1d-·-patch-2-3-rust-page-add-reference-counting-raw-pointers-and-a-private-bit-lock" tabindex="-1"><code>1cfa2b73dc1d</code> · <a href="https://lore.kernel.org/all/20261117233211.3137168-3-vitaly.wool@konsulko.se/" target="_blank" rel="noreferrer">[PATCH 2/3] rust: page: add reference counting, raw pointers and a private bit lock</a> <a class="header-anchor" href="#_1cfa2b73dc1d-·-patch-2-3-rust-page-add-reference-counting-raw-pointers-and-a-private-bit-lock" aria-label="Permalink to &quot;`1cfa2b73dc1d` · [[PATCH 2/3] rust: page: add reference counting, raw pointers and a private bit lock](https://lore.kernel.org/all/20261117233211.3137168-3-vitaly.wool@konsulko.se/)&quot;">​</a></h3><p><em>Vitaly Wool (<a href="mailto:vitaly.wool@konsulko.se" target="_blank" rel="noreferrer">vitaly.wool@konsulko.se</a>)｜rust-for-linux</em></p><p>为 Rust 的 Page 抽象扩展能力：新增 Page::get()（通过 get_page() 增加引用）、Page::into_raw()/from_raw()（与 struct page 指针互转）、Page::try_get_raw()（用 get_page_unless_zero() 从可能失效的指针取引用，支持类似 brd_lookup_page() 的无锁查找），以及基于 page-&gt;private 的位自旋锁。其 soundness 依据是 struct page 结构本身永不释放。</p><blockquote><p><strong>学习价值</strong>：深入讲解 Rust 封装 struct page 时的引用计数与安全性论证，是 Rust 内核抽象设计的经典范例。</p></blockquote><h3 id="_1d87bd9353fd-·-patch-1-3-rust-block-add-bio-segment-iteration-and-request-accessors" tabindex="-1"><code>1d87bd9353fd</code> · <a href="https://lore.kernel.org/all/20261117233211.3137168-2-vitaly.wool@konsulko.se/" target="_blank" rel="noreferrer">[PATCH 1/3] rust: block: add bio segment iteration and request accessors</a> <a class="header-anchor" href="#_1d87bd9353fd-·-patch-1-3-rust-block-add-bio-segment-iteration-and-request-accessors" aria-label="Permalink to &quot;`1d87bd9353fd` · [[PATCH 1/3] rust: block: add bio segment iteration and request accessors](https://lore.kernel.org/all/20261117233211.3137168-2-vitaly.wool@konsulko.se/)&quot;">​</a></h3><p><em>Vitaly Wool (<a href="mailto:vitaly.wool@konsulko.se" target="_blank" rel="noreferrer">vitaly.wool@konsulko.se</a>)｜rust-for-linux</em></p><p>为 Rust blk-mq 抽象补充数据访问能力：现有抽象只支持 null block 驱动所需的请求启停，无法获知请求内容。新增 bio 模块，包含 Bio 包装器、请求内 bio 迭代器和 bio 内单页 segment 迭代器（等价于 rq_for_each_segment()），支持带边界检查的 segment 与 Page 间拷贝及清零，迭代通过包装 bio_iter_iovec() 和 bio_advance_iter() 的新 C helper 实现。</p><blockquote><p><strong>学习价值</strong>：展示了如何为 Rust 驱动补齐 C 侧 bio 遍历基础设施，是理解跨语言抽象层设计的实用素材。</p></blockquote><h3 id="c6ba22e6482b-·-patch-0-3-rust-block-add-rbrd-a-ram-backed-block-driver-1" tabindex="-1"><code>c6ba22e6482b</code> · <a href="https://lore.kernel.org/all/20261117233211.3137168-1-vitaly.wool@konsulko.se/" target="_blank" rel="noreferrer">[PATCH 0/3] rust: block: add rbrd, a RAM backed block driver</a> <a class="header-anchor" href="#c6ba22e6482b-·-patch-0-3-rust-block-add-rbrd-a-ram-backed-block-driver-1" aria-label="Permalink to &quot;`c6ba22e6482b` · [[PATCH 0/3] rust: block: add rbrd, a RAM backed block driver](https://lore.kernel.org/all/20261117233211.3137168-1-vitaly.wool@konsulko.se/)&quot;">​</a></h3><p><em>Vitaly Wool (<a href="mailto:vitaly.wool@konsulko.se" target="_blank" rel="noreferrer">vitaly.wool@konsulko.se</a>)｜rust-for-linux</em></p><p>本系列添加 Rust 编写的 RAM 块设备 rbrd 及所需抽象：1) blk-mq 驱动的 bio segment 迭代与请求访问器；2) Page 的引用计数、裸指针转换和 page-&gt;private 位自旋锁；3) 通过 configfs 配置的驱动本身。page 保存在原子指针扁平数组中实现无锁查找/添加/删除；与 brd 不同，rbrd 用位自旋锁保证读写不会同时拷贝同一 page。</p><blockquote><p><strong>学习价值</strong>：作为完整的三补丁系列，展示了从底层抽象到完整驱动的 Rust 内核开发全流程，非常值得通读。</p></blockquote><h3 id="dc2a63944a3b-·-patch-rust-binder-disallow-binder-fd-transfers" tabindex="-1"><code>dc2a63944a3b</code> · <a href="https://lore.kernel.org/all/20261117231927.2200674-1-cmllamas@google.com/" target="_blank" rel="noreferrer">[PATCH] rust_binder: disallow binder fd transfers</a> <a class="header-anchor" href="#dc2a63944a3b-·-patch-rust-binder-disallow-binder-fd-transfers" aria-label="Permalink to &quot;`dc2a63944a3b` · [[PATCH] rust_binder: disallow binder fd transfers](https://lore.kernel.org/all/20261117231927.2200674-1-cmllamas@google.com/)&quot;">​</a></h3><p><em>Carlos Llamas (<a href="mailto:cmllamas@google.com" target="_blank" rel="noreferrer">cmllamas@google.com</a>)｜rust-for-linux</em></p><p>禁止在 Rust binder 中通过 BINDER_TYPE_FD 或 BINDER_TYPE_FDA 转移 binder 设备 fd。这种转移没有合法用例，且会造成直接引用循环，使排队的 transaction 未读时 Process::release() 无法执行；同时 binder 文件绑定到打开进程的 task、credentials 和 mmap 状态，转移会破坏 per-process 所有权模型。修复方式是在 Allocation::info_add_fd() 中返回 EINVAL。</p><blockquote><p><strong>学习价值</strong>：揭示了 binder fd 生命周期与引用循环问题，对理解 Android IPC 安全模型很有帮助。</p></blockquote><h3 id="_7eb42ece6eb5-·-patch-4-4-drm-tyr-vm-check-the-remaining-length-in-pt-unmap" tabindex="-1"><code>7eb42ece6eb5</code> · <a href="https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-4-2a8efd4c8180@google.com/" target="_blank" rel="noreferrer">[PATCH 4/4] drm/tyr: vm: check the remaining length in pt_unmap()</a> <a class="header-anchor" href="#_7eb42ece6eb5-·-patch-4-4-drm-tyr-vm-check-the-remaining-length-in-pt-unmap" aria-label="Permalink to &quot;`7eb42ece6eb5` · [[PATCH 4/4] drm/tyr: vm: check the remaining length in pt_unmap()](https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-4-2a8efd4c8180@google.com/)&quot;">​</a></h3><p><em>Alice Ryhl (<a href="mailto:aliceryhl@google.com" target="_blank" rel="noreferrer">aliceryhl@google.com</a>)｜rust-for-linux</em></p><p>修复 drm/tyr GPU 驱动 vm.rs 中 pt_unmap() 的长度下溢问题：该函数从剩余长度中减去每次取消映射的块大小，并依赖 unmap_pages() 不会多解除映射。补丁增加对该减法的检查，下溢时返回 EINVAL，并使用安全类型转换替代 &#39;as&#39;。</p><blockquote><p><strong>学习价值</strong>：体现了 Rust 驱动中用类型系统防御算术下溢的实践，小而精的防御性编程示例。</p></blockquote><h3 id="_2adb87acefd2-·-patch-3-4-drm-tyr-vm-expand-sub-block-unmaps-to-2mb-boundaries-on-remap" tabindex="-1"><code>2adb87acefd2</code> · <a href="https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-3-2a8efd4c8180@google.com/" target="_blank" rel="noreferrer">[PATCH 3/4] drm/tyr: vm: expand sub-block unmaps to 2MB boundaries on remap</a> <a class="header-anchor" href="#_2adb87acefd2-·-patch-3-4-drm-tyr-vm-expand-sub-block-unmaps-to-2mb-boundaries-on-remap" aria-label="Permalink to &quot;`2adb87acefd2` · [[PATCH 3/4] drm/tyr: vm: expand sub-block unmaps to 2MB boundaries on remap](https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-3-2a8efd4c8180@google.com/)&quot;">​</a></h3><p><em>Alice Ryhl (<a href="mailto:aliceryhl@google.com" target="_blank" rel="noreferrer">aliceryhl@google.com</a>)｜rust-for-linux</em></p><p>修复 drm/tyr 的 VM 重映射问题：GEM shmem 由透明大页支撑时 Tyr 会安装 2MB block entry，而 arm-lpae 拒绝部分解除 block 映射，导致 sm_step_remap 中的稀疏部分重绑定失败并毒化 VM。修复将此类 unmap 扩展到 block 边界并重建存活片段，仅在连续时扩展。</p><blockquote><p><strong>学习价值</strong>：展示了 GPU 页表 block entry 与 arm-lpae IOMMU 格式交互的细节，适合学习 GPU VM 管理。</p></blockquote><h3 id="f9b2df7f5c19-·-patch-2-4-rust-iommu-pgtable-add-iova-to-phys" tabindex="-1"><code>f9b2df7f5c19</code> · <a href="https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-2-2a8efd4c8180@google.com/" target="_blank" rel="noreferrer">[PATCH 2/4] rust: iommu: pgtable: add iova_to_phys</a> <a class="header-anchor" href="#f9b2df7f5c19-·-patch-2-4-rust-iommu-pgtable-add-iova-to-phys" aria-label="Permalink to &quot;`f9b2df7f5c19` · [[PATCH 2/4] rust: iommu: pgtable: add iova_to_phys](https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-2-2a8efd4c8180@google.com/)&quot;">​</a></h3><p><em>Alice Ryhl (<a href="mailto:aliceryhl@google.com" target="_blank" rel="noreferrer">aliceryhl@google.com</a>)｜rust-for-linux</em></p><p>为 Rust iommu pgtable 抽象层新增 IoPageTable::iova_to_phys() 方法，用于查询某个 iova 映射到的物理地址。这是 Tyr 驱动 VM_BIND remap 路径的支撑补丁：部分 unmap 会扫掉一些页表映射，remap 时需要从仍存在的表项中恢复其物理后备地址。改动仅涉及 rust/kernel/iommu/pgtable.rs，新增 23 行。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 内核抽象层如何为驱动需求逐步补充 API，是理解 iommu pgtable 抽象与 GPU 驱动协作的好例子。</p></blockquote><h3 id="cb9340a0506e-·-patch-1-4-rust-drm-gpuvm-add-gpuva-data-ref-accessor" tabindex="-1"><code>cb9340a0506e</code> · <a href="https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-1-2a8efd4c8180@google.com/" target="_blank" rel="noreferrer">[PATCH 1/4] rust: drm/gpuvm: add GpuVa::data_ref accessor</a> <a class="header-anchor" href="#cb9340a0506e-·-patch-1-4-rust-drm-gpuvm-add-gpuva-data-ref-accessor" aria-label="Permalink to &quot;`cb9340a0506e` · [[PATCH 1/4] rust: drm/gpuvm: add GpuVa::data_ref accessor](https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-1-2a8efd4c8180@google.com/)&quot;">​</a></h3><p><em>Alice Ryhl (<a href="mailto:aliceryhl@google.com" target="_blank" rel="noreferrer">aliceryhl@google.com</a>)｜rust-for-linux</em></p><p>为 Rust DRM GPUVM 抽象中的 GpuVa 新增 data_ref() 访问器，允许读取已有映射的 VaData。Tyr 驱动的 VM_BIND remap 路径在拆分 2MB block 后需要重建幸存 fragment 的映射，且这些 fragment 必须保留原映射的保护标志，因此需要读取已有映射的 VaData。改动仅 6 行，位于 rust/kernel/drm/gpuvm/va.rs。</p><blockquote><p><strong>学习价值</strong>：体现了 Rust 抽象层中访问器设计如何服务于上层驱动的 remap 逻辑，适合学习 DRM GPUVM 的 VA 管理模型。</p></blockquote><h3 id="edec5cf4f4e5-·-patch-0-4-drm-tyr-fix-partial-2mb-block-unmaps-on-gpuvm-remap" tabindex="-1"><code>edec5cf4f4e5</code> · <a href="https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-0-2a8efd4c8180@google.com/" target="_blank" rel="noreferrer">[PATCH 0/4] drm/tyr: fix partial 2MB block unmaps on GPUVM remap</a> <a class="header-anchor" href="#edec5cf4f4e5-·-patch-0-4-drm-tyr-fix-partial-2mb-block-unmaps-on-gpuvm-remap" aria-label="Permalink to &quot;`edec5cf4f4e5` · [[PATCH 0/4] drm/tyr: fix partial 2MB block unmaps on GPUVM remap](https://lore.kernel.org/all/20261117-tyr-remap-2mb-v1-0-2a8efd4c8180@google.com/)&quot;">​</a></h3><p><em>Alice Ryhl (<a href="mailto:aliceryhl@google.com" target="_blank" rel="noreferrer">aliceryhl@google.com</a>)｜rust-for-linux</em></p><p>本系列修复 Tyr DRM 驱动在 GPUVM remap 时部分 unmap 2MB block 失败的问题：Tyr 的 ARM64 LPAE 页表使用 4KB 和 2MB block 尺寸，但 arm-lpae 拒绝对 2MB block 的部分 unmap，导致 GpuVmData::sm_step_remap() 在 __arm_lpae_unmap() 中失败。修复方案将 tyr-dev 上的 remap 补丁移植到 drm-rust-next，包括新增 GpuVa::data_ref() 和 IoPageTable::iova_to_phys() 访问器、在 sm_step_remap() 中将 sub-block unmap 扩展到 2MB 边界（当被扫除的头/尾 fragment 物理连续时），以及 pt_unmap() 中的防御性边界检查。</p><blockquote><p><strong>学习价值</strong>：完整呈现了从底层 iommu 页表限制到上层 GPU 驱动 remap 逻辑的 bug 定位与修复链路，是学习 GPU 驱动与 IOMMU 交互的优质案例。</p></blockquote><h3 id="_6f58d1025ebe-·-patch-v2-2-2-rust-str-add-an-example-for-formatter-new" tabindex="-1"><code>6f58d1025ebe</code> · <a href="https://lore.kernel.org/all/20261117-formatter-lifetime-v2-2-e216d86ffb57@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 2/2] rust: str: add an example for Formatter::new</a> <a class="header-anchor" href="#_6f58d1025ebe-·-patch-v2-2-2-rust-str-add-an-example-for-formatter-new" aria-label="Permalink to &quot;`6f58d1025ebe` · [[PATCH v2 2/2] rust: str: add an example for Formatter::new](https://lore.kernel.org/all/20261117-formatter-lifetime-v2-2-e216d86ffb57@gmail.com/)&quot;">​</a></h3><p><em>Peder Bergan via B4 Relay (<a href="mailto:devnull+peder.bergan.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+peder.bergan.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>为 rust/kernel/str.rs 中的 Formatter::new() 补充文档示例，说明其持有的独占 buffer 借用，并演示向活跃 buffer 进行格式化写入，同时校验写入字节数和最终 buffer 内容。这是与 lifetime 修复配套的文档补丁（v2 按审阅意见拆分而来），新增 16 行。</p><blockquote><p><strong>学习价值</strong>：展示了内核 Rust 文档补丁的规范写法，doctest 示例对理解 Formatter 的借用语义很有帮助。</p></blockquote><h3 id="_6841e9ae87d9-·-patch-v2-1-2-rust-str-tie-formatter-to-its-backing-buffer" tabindex="-1"><code>6841e9ae87d9</code> · <a href="https://lore.kernel.org/all/20261117-formatter-lifetime-v2-1-e216d86ffb57@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 1/2] rust: str: tie Formatter to its backing buffer</a> <a class="header-anchor" href="#_6841e9ae87d9-·-patch-v2-1-2-rust-str-tie-formatter-to-its-backing-buffer" aria-label="Permalink to &quot;`6841e9ae87d9` · [[PATCH v2 1/2] rust: str: tie Formatter to its backing buffer](https://lore.kernel.org/all/20261117-formatter-lifetime-v2-1-e216d86ffb57@gmail.com/)&quot;">​</a></h3><p><em>Peder Bergan via B4 Relay (<a href="mailto:devnull+peder.bergan.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+peder.bergan.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>修复 rust/kernel/str.rs 中 Formatter 的 use-after-free 问题：原 Formatter::new() 返回的 Formatter 生命周期与其 backing buffer 的借用无关，安全代码可以先 drop buffer 再通过 formatter 写入，造成 use-after-free。修复将 buffer 借用绑定到 formatter 的生命周期，使 borrow checker 能拒绝此类调用并阻止重叠的可变访问。修复 commit 87482d6d9104，已抄送 stable。</p><blockquote><p><strong>学习价值</strong>：经典的 Rust lifetime 约束修复案例，说明即使安全 Rust 抽象设计不当也会引入内存安全问题，对理解生命周期与借用检查很有价值。</p></blockquote><h3 id="_4f911ee913f5-·-patch-v2-0-2-rust-str-tie-formatter-to-its-backing-buffer" tabindex="-1"><code>4f911ee913f5</code> · <a href="https://lore.kernel.org/all/20261117-formatter-lifetime-v2-0-e216d86ffb57@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 0/2] rust: str: tie Formatter to its backing buffer</a> <a class="header-anchor" href="#_4f911ee913f5-·-patch-v2-0-2-rust-str-tie-formatter-to-its-backing-buffer" aria-label="Permalink to &quot;`4f911ee913f5` · [[PATCH v2 0/2] rust: str: tie Formatter to its backing buffer](https://lore.kernel.org/all/20261117-formatter-lifetime-v2-0-e216d86ffb57@gmail.com/)&quot;">​</a></h3><p><em>Peder Bergan via B4 Relay (<a href="mailto:devnull+peder.bergan.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+peder.bergan.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>本系列（v2）将 Formatter 生命周期修复与其文档示例拆分为两个补丁，按 Gary 的审阅意见调整。作者用 Clippy 编译了仅含修复的第一个补丁，并在 x86_64 QEMU 下运行了字符串测试和内核 doctest。修复内容为将 Formatter 绑定到其 backing buffer 的借用，防止 use-after-free；OpenAI Codex 辅助了编码和测试。</p><blockquote><p><strong>学习价值</strong>：展示了内核补丁迭代中拆分 patch、测试验证的标准流程，也反映了 AI 工具参与内核开发的现状。</p></blockquote><h2 id="核心内核" tabindex="-1">核心内核 <a class="header-anchor" href="#核心内核" aria-label="Permalink to &quot;核心内核&quot;">​</a></h2><h3 id="c9cd219a6c7e-·-new-amdgpu-linux-patches-from-valve-aim-to-reduce-stuttering-with-steam-play-games-1" tabindex="-1"><code>c9cd219a6c7e</code> · <a href="https://www.phoronix.com/news/AMDGPU-Sparse-Gaming-Valve" target="_blank" rel="noreferrer">New AMDGPU Linux Patches From Valve Aim To Reduce Stuttering With Steam Play Games</a> <a class="header-anchor" href="#c9cd219a6c7e-·-new-amdgpu-linux-patches-from-valve-aim-to-reduce-stuttering-with-steam-play-games-1" aria-label="Permalink to &quot;`c9cd219a6c7e` · [New AMDGPU Linux Patches From Valve Aim To Reduce Stuttering With Steam Play Games](https://www.phoronix.com/news/AMDGPU-Sparse-Gaming-Valve)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Valve Linux 图形驱动团队的 Natalie Vock 发送了新版 AMDGPU 内核驱动补丁，旨在为通过 Steam Play（Proton）在 Linux 上运行的新 Windows 游戏带来显著的卡顿减少。</p><blockquote><p><strong>学习价值</strong>：展示了游戏厂商如何直接参与内核图形驱动开发，是理解 AMDGPU 驱动与实际性能调优结合的好案例。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_8893b59b5ae2-·-three-stable-kernels-for-tuesday" tabindex="-1"><code>8893b59b5ae2</code> · <a href="https://lwn.net/Articles/1108142/" target="_blank" rel="noreferrer">Three stable kernels for Tuesday</a> <a class="header-anchor" href="#_8893b59b5ae2-·-three-stable-kernels-for-tuesday" aria-label="Permalink to &quot;`8893b59b5ae2` · [Three stable kernels for Tuesday](https://lwn.net/Articles/1108142/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Greg Kroah-Hartman 发布了 7.3.5、6.18.64 和 6.12.118 三个 stable 内核版本，每个版本都包含大量重要修复。</p><blockquote><p><strong>学习价值</strong>：跟踪 stable 内核发布节奏是了解内核维护流程和补丁回溯机制的入门实践。</p></blockquote><h3 id="bde8d48eaa85-·-next-20261117-linux-next" tabindex="-1"><code>bde8d48eaa85</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261117-2026-11-17" target="_blank" rel="noreferrer">next-20261117: linux-next</a> <a class="header-anchor" href="#bde8d48eaa85-·-next-20261117-linux-next" aria-label="Permalink to &quot;`bde8d48eaa85` · [next-20261117: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261117-2026-11-17)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026-11-17 发布 next-20261117 版本。linux-next 是各子系统树合并后的集成测试树，供下一次合并窗口前的整体测试使用。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 发布节奏有助于学习者了解内核开发流程中补丁集成与测试的阶段。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="a237c4bb18ba-·-redict-deprecated-in-favor-of-valkey" tabindex="-1"><code>a237c4bb18ba</code> · <a href="https://lwn.net/Articles/1108155/" target="_blank" rel="noreferrer">Redict deprecated in favor of Valkey</a> <a class="header-anchor" href="#a237c4bb18ba-·-redict-deprecated-in-favor-of-valkey" aria-label="Permalink to &quot;`a237c4bb18ba` · [Redict deprecated in favor of Valkey](https://lwn.net/Articles/1108155/)&quot;">​</a></h3><p><em>daroc｜lwn</em></p><p>Drew DeVault 宣布弃用 Redict——这是 2024 年 Redis 许可证变更后诞生的 copyleft 分支。他建议用户迁移到由 Linux Foundation 支持的宽松许可证分支 Valkey，两者相互兼容，切换只需更换软件包并重命名配置文件。</p><blockquote><p><strong>学习价值</strong>：与内核学习关系不大，但有助于了解开源许可证变更引发的生态分裂与社区治理动态。</p></blockquote><h3 id="a28348aa541c-·-zellij-manages-terminal-workspaces-with-style" tabindex="-1"><code>a28348aa541c</code> · <a href="https://lwn.net/Articles/1106913/" target="_blank" rel="noreferrer">[$] Zellij manages terminal workspaces with style</a> <a class="header-anchor" href="#a28348aa541c-·-zellij-manages-terminal-workspaces-with-style" aria-label="Permalink to &quot;`a28348aa541c` · [[$] Zellij manages terminal workspaces with style](https://lwn.net/Articles/1106913/)&quot;">​</a></h3><p><em>jzb｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>Zellij 是终端复用器领域的新成员，类似 GNU Screen 和 tmux，提供分屏和会话管理，同时增加了浏览器访问终端的 web server、插件 API 扩展机制，对新手更友好。最新 0.46 版本加入了独立终端模拟器、内置通知收件箱和图形化设置界面。</p><blockquote><p><strong>学习价值</strong>：属于开发工具资讯，可作为内核开发者日常终端工作流选型的参考，与内核本身无直接关系。</p></blockquote><h3 id="_2ab28621e134-·-freebsd-desktop-install-option-pushed-back-to-next-year-with-freebsd-15-3" tabindex="-1"><code>2ab28621e134</code> · <a href="https://www.phoronix.com/news/FreeBSD-Desktop-Install-15.3" target="_blank" rel="noreferrer">FreeBSD Desktop Install Option Pushed Back To Next Year With FreeBSD 15.3</a> <a class="header-anchor" href="#_2ab28621e134-·-freebsd-desktop-install-option-pushed-back-to-next-year-with-freebsd-15-3" aria-label="Permalink to &quot;`2ab28621e134` · [FreeBSD Desktop Install Option Pushed Back To Next Year With FreeBSD 15.3](https://www.phoronix.com/news/FreeBSD-Desktop-Install-15.3)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>FreeBSD 计划中的 KDE 桌面安装选项一再推迟，从 15.0 到 15.1 再到 15.2，目前预计要到 2027 年中的 FreeBSD 15.3 才能实现。</p><blockquote><p><strong>学习价值</strong>：BSD 生态资讯，可作为对比 Linux 发行版桌面集成策略的参考，与 Linux 内核学习无直接关系。</p></blockquote><h3 id="_1d5460c3d32f-·-framework-wireless-touchpad-keyboard-to-sell-for-99-usd-begins-shipping-in-q1" tabindex="-1"><code>1d5460c3d32f</code> · <a href="https://www.phoronix.com/news/Framework-Wireless-Keyboard" target="_blank" rel="noreferrer">Framework Wireless Touchpad Keyboard To Sell For $99 USD, Begins Shipping In Q1</a> <a class="header-anchor" href="#_1d5460c3d32f-·-framework-wireless-touchpad-keyboard-to-sell-for-99-usd-begins-shipping-in-q1" aria-label="Permalink to &quot;`1d5460c3d32f` · [Framework Wireless Touchpad Keyboard To Sell For $99 USD, Begins Shipping In Q1](https://www.phoronix.com/news/Framework-Wireless-Keyboard)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Framework Computer 的无线触控板键盘开放预订，售价 99 美元，预计 2027 年第一季度开始发货。</p><blockquote><p><strong>学习价值</strong>：硬件产品资讯，与内核学习无关。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>12b0d9a577ed</code> · <a href="https://lore.kernel.org/all/b56bbced-a8b0-4ae9-80b4-1958ea36684c@mid.andrii.net/" target="_blank" rel="noreferrer">[PATCH ipsec 0/2] xfrm: iptfs: fix a panic and a use-after-free on output</a></li><li><code>3684d9b9a919</code> · <a href="https://lore.kernel.org/all/20261118005048.53393-1-mason@kernel.org/" target="_blank" rel="noreferrer">[PATCH net 0/3] tcp: avoid integer wraps in the RTT estimator and the RTO</a></li><li><code>c6ba22e6482b</code> · <a href="https://lore.kernel.org/all/20261117233211.3137168-1-vitaly.wool@konsulko.se/" target="_blank" rel="noreferrer">[PATCH 0/3] rust: block: add rbrd, a RAM backed block driver</a></li><li><code>cb72b626bf2a</code> · <a href="https://lore.kernel.org/all/20261118-pagemap-walk-end-v2-1-94cd92d838b3@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2 1/2] fs/proc/task_mmu: reset walk_end before each pagemap walk</a></li><li><code>c9cd219a6c7e</code> · <a href="https://www.phoronix.com/news/AMDGPU-Sparse-Gaming-Valve" target="_blank" rel="noreferrer">New AMDGPU Linux Patches From Valve Aim To Reduce Stuttering With Steam Play Games</a></li></ul>',190)])])}const h=a(l,[["render",n]]);export{m as __pageData,h as default};
